  handleSelectAll = () => {
    this.setState(state => {
      const { filterRows } = this.props;
      const { filterInputValue, rowIds, rowsById, cellsById } = state;

      // Determine the set of visible (filtered) rows
      const filteredRowIds =
        typeof filterInputValue === 'string'
          ? filterRows({
              rowIds,
              headers: this.props.headers,
              cellsById,
              inputValue: filterInputValue,
            })
          : rowIds;

      // Count how many visible rows can be selected
      const selectableVisible = filteredRowIds.reduce((acc, id) => {
        return acc + (rowsById[id].disabled ? 0 : 1);
      }, 0);

      // Should we select or unselect them?
      const currentlySelectedVisible = filteredRowIds.filter(
        id => rowsById[id].isSelected
      ).length;
      const isSelected = currentlySelectedVisible !== selectableVisible;

      // Build new rowsById toggling only the visible rows
      const newRowsById = { ...rowsById };
